import{_ as a,c as e,a as t,b as l,w as d,u as o,d as i,o as f,I as v}from"./index-b8d38dfd.js";const c="/assets/ches3-423fef86.jpg",p="/assets/strelka3-27b6f1bb.jpg",n="/assets/chess_160-dbd4f3a3.jpg";const r={class:"container"},_={class:"section"},x={class:"forimg full"},m={__name:"ProChesnok",setup(u){return(g,s)=>(f(),e("div",r,[s[2]||(s[2]=t("h2",null,"Всё PRO чеснок",-1)),s[3]||(s[3]=t("div",{class:"section"},[t("p",{class:"text"},"Чеснок - одна из самых популярных и востребованных приправ на свете: практически любое блюдо сопровождается использованием чеснока. В каждом доме едят чеснок как сырым, так и в блюдах. В чем же заключается такая популярность?")],-1)),t("div",_,[t("div",x,[l(o(v),null,{default:d(()=>[...s[0]||(s[0]=[t("img",{slot:"first",style:{width:"100%"},src:c},null,-1),t("img",{slot:"second",style:{width:"100%"},src:p},null,-1)])]),_:1})]),s[1]||(s[1]=t("div",{class:"fortext"},[t("p",{class:"text"},"Чеснок - древнейшее культурное растение, которое возделывается со времен неолита. Главное преимущество использования чеснока в пищу заключается в его бактерицидном действии, убивая болезнетворные бактерии как в сыром виде, так и термически обработанном. "),t("p",{class:"text"},"Луковицы чеснока содержат эфирные масла, гликозид аллин, витамины группы В и С, магний, кальций, фосфор, йод, хлор и множество других микроэлементов. Чеснок нормализует обмен веществ, понижает давление, помогает выведению холестерина")],-1))]),s[4]||(s[4]=i('<div class="section" data-v-5f49887e><div class="fortext" data-v-5f49887e><p class="text" data-v-5f49887e>Сегодня существует около 300 разновидностей чеснока.</p><p class="text" data-v-5f49887e> Для выращивания на нашем хозяйстве были выбраны несколько сортов чеснока, таких как «ЛЮБАША», «ДОБРЫНЯ», «БОГАТЫРЬ».</p></div><div class="forimg w-40" data-v-5f49887e><img src="'+n+'" data-v-5f49887e></div></div><h2 data-v-5f49887e>Преимущества сортового чеснока</h2><div class="section" data-v-5f49887e><ol data-v-5f49887e><li data-v-5f49887e><p class="text" data-v-5f49887e>Данные сорта отличается отличными морозостойкими характеристиками, которые выдерживают понижение температуры до -38°C, так как являются озимыми;</p></li><li data-v-5f49887e><p class="text" data-v-5f49887e>Созревшие луковицы ВЫСШЕГО СОРТА отличаются большими размерами 100-140г;</p></li><li data-v-5f49887e><p class="text" data-v-5f49887e>Луковица состоит из 6-8 зубчиков;</p></li><li data-v-5f49887e><p class="text" data-v-5f49887e>Чеснок с острым перечным привкусом, что превосходно подходит для кулинарии;</p></li><li data-v-5f49887e><p class="text" data-v-5f49887e>Чеснок отличается высокой длительностью хранения. При соблюдении правил хранения, чеснок будет радовать вас своими вкусовыми качествами на протяжении 12 месяцев. Для этого необходимо исключить сквозняки и попадание влаги. При обеспечении температуры хранения -2°С наш чеснок может храниться до 3 лет. При такой температуре чеснок впадает в состояние анабиоза, в нем замедляются процессы роста. Но, как только внешняя температура переступит 0°С, чеснок возобновит свой рост.</p></li></ol></div><h4 data-v-5f49887e>2025©</h4><br data-v-5f49887e>',5))]))}},b=a(m,[["__scopeId","data-v-5f49887e"]]);export{b as default};
